// Generates the app's icon (a coin with an upward arrow) in every
// size web and Android need, from a single set of vector
// coordinates defined right here (see docs/design.md, "Identidad
// visual"). Also writes `assets/branding/icon.svg`: the same
// drawing in SVG, to have a readable vector source in the repo —
// generated by this script, never by hand, so it never drifts out
// of sync with the PNGs.
//
// Not a test: it makes no assertion, it only writes files. Lives
// outside `test/` on purpose so `flutter test` (with no arguments)
// never picks it up or counts it. Run by hand:
//
//   flutter test tool/generate_icons.dart
//
// Uses `flutter test` only because it's this project's only entry
// point with the Flutter engine already initialized to be able to
// rasterize with `dart:ui` (no SVG rasterizer was installed when
// this was written); `lib/eval_main.dart` uses `flutter run` for an
// equivalent reason (see "Por qué no puede ser un script de Dart
// puro ni correr en CI" in docs/evaluation.md).

import 'dart:io';
import 'dart:typed_data';
import 'dart:ui';

import 'package:flutter_test/flutter_test.dart';

/// Near-black dark background with a greenish tint: the same
/// `surface` as `AppTheme.dark()` (`lib/presentation/theme/app_theme.dart`).
const _backgroundColor = 0xFF0B120F;

/// Teal/mint: the same `primary` as `AppTheme.dark()`.
const _symbolColor = 0xFF4DB6AC;

/// Monochrome icon (Android 13+): a single shape with alpha, no
/// color of its own — the system tints it with whatever color it
/// chooses. The exact value doesn't matter, only that it has alpha
/// 255 wherever the symbol shows; black is used by convention.
const _monochromeColor = 0xFF000000;

/// The whole drawing lives on a 100x100-unit square canvas, sized
/// to fit inside the stricter of the two circular safe zones this
/// icon requires: the 66dp circle over a 108dp canvas of an Android
/// adaptive icon (radius ≈30.5% of the canvas, measured from the
/// center). The point farthest from the center here is the coin's
/// base, at 23 units — with plenty of margin under that 30.5%. That
/// same geometry, by fitting the stricter circular zone, also fits
/// inside the "central 80%" safe zone (square, more lenient) web
/// maskable icons ask for: a single geometry serves both without
/// needing two variants.
void _paintSymbol(Canvas canvas, double size, int color) {
  final scale = size / 100;
  final paint = Paint()..color = Color(color);

  // Coin.
  canvas.drawCircle(Offset(50 * scale, 60 * scale), 13 * scale, paint);

  // Arrow shaft, joining the coin to the tip.
  canvas.drawRect(Rect.fromLTWH(46 * scale, 46 * scale, 8 * scale, 14 * scale), paint);

  // Arrow tip.
  final arrowHead = Path()
    ..moveTo(38 * scale, 46 * scale)
    ..lineTo(62 * scale, 46 * scale)
    ..lineTo(50 * scale, 28 * scale)
    ..close();
  canvas.drawPath(arrowHead, paint);
}

Future<Uint8List> _renderPng({
  required double size,
  required bool withBackground,
  int symbolColor = _symbolColor,
}) async {
  final recorder = PictureRecorder();
  final canvas = Canvas(recorder);
  if (withBackground) {
    canvas.drawRect(Rect.fromLTWH(0, 0, size, size), Paint()..color = const Color(_backgroundColor));
  }
  _paintSymbol(canvas, size, symbolColor);
  final picture = recorder.endRecording();
  final image = await picture.toImage(size.round(), size.round());
  final bytes = await image.toByteData(format: ImageByteFormat.png);
  return bytes!.buffer.asUint8List();
}

Future<void> _writePng(
  String path, {
  required double size,
  required bool withBackground,
  int symbolColor = _symbolColor,
}) async {
  final bytes = await _renderPng(size: size, withBackground: withBackground, symbolColor: symbolColor);
  final file = File(path);
  await file.parent.create(recursive: true);
  await file.writeAsBytes(bytes);
  // ignore: avoid_print
  print('Escrito: $path (${size.round()}x${size.round()})');
}

String _buildSvg() {
  return '''
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
  <!-- Generado por tool/generate_icons.dart — no editar a mano, ver docs/design.md "Identidad visual". -->
  <rect width="100" height="100" fill="#0B120F"/>
  <g fill="#4DB6AC">
    <circle cx="50" cy="60" r="13"/>
    <rect x="46" y="46" width="8" height="14"/>
    <polygon points="38,46 62,46 50,28"/>
  </g>
</svg>
''';
}

void main() {
  testWidgets('generar los iconos de la app (herramienta, no un test de comportamiento)', (tester) async {
    // `toImage`/`toByteData` are genuinely async (they decode with
    // the engine, not with `flutter test`'s fake clock): without
    // `runAsync` they never resolve inside a normal `testWidgets`.
    await tester.runAsync(() async {
      final svgFile = File('assets/branding/icon.svg');
      await svgFile.parent.create(recursive: true);
      await svgFile.writeAsString(_buildSvg());
      // ignore: avoid_print
      print('Escrito: ${svgFile.path}');

      // Web: "any" icons (with a full-bleed background) and
      // maskable ones (same full-bleed background; the symbol
      // already fits the safe zone — see `_paintSymbol`'s comment).
      await _writePng('web/favicon.png', size: 16, withBackground: true);
      await _writePng('web/icons/Icon-192.png', size: 192, withBackground: true);
      await _writePng('web/icons/Icon-512.png', size: 512, withBackground: true);
      await _writePng('web/icons/Icon-maskable-192.png', size: 192, withBackground: true);
      await _writePng('web/icons/Icon-maskable-512.png', size: 512, withBackground: true);

      // Android: legacy icon (pre-Android 8, with background) in
      // the 5 standard densities.
      const legacySizes = {
        'mdpi': 48.0,
        'hdpi': 72.0,
        'xhdpi': 96.0,
        'xxhdpi': 144.0,
        'xxxhdpi': 192.0,
      };
      for (final entry in legacySizes.entries) {
        await _writePng(
          'android/app/src/main/res/mipmap-${entry.key}/ic_launcher.png',
          size: entry.value,
          withBackground: true,
        );
      }

      // Android: adaptive icon (foreground, no background — the
      // background is the `ic_launcher_background` resource color,
      // see `android/app/src/main/res/values/colors.xml`) and its
      // monochrome version (Android 13+), on a 108dp canvas per
      // density.
      const adaptiveSizes = {
        'mdpi': 108.0,
        'hdpi': 162.0,
        'xhdpi': 216.0,
        'xxhdpi': 324.0,
        'xxxhdpi': 432.0,
      };
      for (final entry in adaptiveSizes.entries) {
        await _writePng(
          'android/app/src/main/res/mipmap-${entry.key}/ic_launcher_foreground.png',
          size: entry.value,
          withBackground: false,
        );
        await _writePng(
          'android/app/src/main/res/mipmap-${entry.key}/ic_launcher_monochrome.png',
          size: entry.value,
          withBackground: false,
          symbolColor: _monochromeColor,
        );
      }
    });
  });
}
